# Lab 17 - classroom sensor node and radio relay (BEFORE the design review).
# Flash the SAME file on every board. ROLE = "relay" on the one board on the PC's USB
# cable, "sensor" on the others (set DEV to a unique name; on a board use machine.unique_id()).
# Sensor: every SAMPLE_MS take temp/light/motion, send it with lab 12's stop-and-wait ARQ.
# Relay: ack every data frame, drop duplicates per device, print a lab 15 serial frame.
# Works for ONE sensor. In a classroom of six it does not: see the README.
from microbit import *
import radio

GROUP = 17
SAMPLE_MS = 1000
TIMEOUT_MS = 100                 # first retransmit deadline; doubles, capped
MAX_TIMEOUT_MS = 800
MAX_TRIES = 6
QUEUE = 3                        # radio default: 3 frames, the rest are dropped
radio.config(group=GROUP, queue=QUEUE)
KEYS = ("tx", "retx", "acked", "gave_up", "rx", "bad", "dup", "fwd")


def crc16(text):
    # CRC-16/CCITT-FALSE, as in labs 12 and 15
    crc = 0xFFFF
    for ch in text:
        crc ^= ord(ch) << 8
        for _ in range(8):
            crc = ((crc << 1) ^ 0x1021) if crc & 0x8000 else (crc << 1)
            crc &= 0xFFFF
    return crc


def encode(kind, dev, seq, payload=""):
    body = "{}:{}:{}:{}".format(kind, dev, seq, payload)    # D = data, A = ack
    return "{}:{:04X}".format(body, crc16(body))


def decode(text):
    body, sep, check = text.rpartition(":")
    if not sep or len(check) != 4:
        return None
    try:
        if int(check, 16) != crc16(body):
            return None
        kind, dev, seq, payload = body.split(":", 3)
        return kind, dev, int(seq), payload
    except ValueError:
        return None


def new_state(role, dev, start_ms=0):
    return {"role": role, "dev": dev, "seq": 0, "queue": [], "inflight": None,
            "next_sample": start_ms, "last": {}, "stats": dict((k, 0) for k in KEYS)}


def sample(now):
    motion = 1 if accelerometer.was_gesture("shake") else 0
    return "{},{},{},{}".format(now, temperature(), display.read_light_level(), motion)


def first_timeout(state):
    return TIMEOUT_MS            # identical on every board: retries stay in lock-step


def pump(state, now):
    st, fl = state["stats"], state["inflight"]
    if fl is None and state["queue"]:
        state["seq"] += 1
        fl = state["inflight"] = {"seq": state["seq"], "tries": 0, "deadline": now,
                                  "timeout": first_timeout(state),
                                  "frame": encode("D", state["dev"], state["seq"], state["queue"].pop(0))}
    if fl is None or now < fl["deadline"]:
        return
    if fl["tries"] >= MAX_TRIES:
        st["gave_up"] += 1
        state["inflight"] = None
        return
    if fl["tries"]:
        st["retx"] += 1
        fl["timeout"] = min(fl["timeout"] * 2, MAX_TIMEOUT_MS)
    radio.send(fl["frame"])
    st["tx"] += 1
    fl["tries"] += 1
    fl["deadline"] = now + fl["timeout"]


def forward(state, dev, seq, payload):
    line = "{},{},{}".format(dev, seq, payload)                 # serial frame from lab 15
    print("${:03d}{}*{:04X}".format(len(line), line, crc16(line)))
    state["stats"]["fwd"] += 1


def on_frame(state, msg):
    st, (kind, dev, seq, payload) = state["stats"], msg
    if state["role"] == "relay" and kind == "D":
        radio.send(encode("A", dev, seq))                       # ack every copy
        if seq <= state["last"].get(dev, 0):
            st["dup"] += 1
            return
        state["last"][dev] = seq
        forward(state, dev, seq, payload)
    elif kind == "A" and dev == state["dev"]:
        fl = state["inflight"]
        if fl and seq == fl["seq"]:
            st["acked"] += 1
            state["inflight"] = None


def receive(state):
    while True:
        try:
            text = radio.receive()
        except ValueError:
            text = "?"
        if text is None:
            return
        state["stats"]["rx"] += 1
        msg = decode(text)
        if msg is None:
            state["stats"]["bad"] += 1
        else:
            on_frame(state, msg)


def step(state, now):
    if state["role"] == "sensor" and now >= state["next_sample"]:
        state["queue"].append(sample(now))
        state["next_sample"] += SAMPLE_MS
    receive(state)
    if state["role"] == "sensor":
        pump(state, now)


def main(role="sensor", dev="n1"):
    state = new_state(role, dev)
    while True:
        step(state, running_time())
        sleep(10)


if __name__ == "__main__":
    main()

# Lab 18 - device side of fleet configuration (BEFORE the design review).
# Config = version + key=value pairs: i (sample interval ms), th (temperature alarm C), g (radio group).
# Gateway -> device: C:<dev>:<ver>:<cfg>   Device -> gateway: A:<dev>:<ver> (applied), N (invalid)
# One-phase: the device APPLIES a new config the moment it arrives, then acks. If the ack is lost,
# or the new config cuts the device off (wrong radio group), it runs a config nobody acknowledged.
from microbit import *
import radio

GROUP = 18
radio.config(group=GROUP)
LIMITS = {"i": (100, 60000), "th": (0, 50), "g": (0, 255)}
FACTORY = {"v": 1, "i": 1000, "th": 30, "g": GROUP}


def crc16(text):
    crc = 0xFFFF
    for ch in text:
        crc ^= ord(ch) << 8
        for _ in range(8):
            crc = ((crc << 1) ^ 0x1021) if crc & 0x8000 else (crc << 1)
            crc &= 0xFFFF
    return crc


def encode(kind, dev, ver, payload=""):
    body = "{}:{}:{}:{}".format(kind, dev, ver, payload)
    return "{}:{:04X}".format(body, crc16(body))


def decode(text):
    body, sep, check = text.rpartition(":")
    if not sep or len(check) != 4:
        return None
    try:
        if int(check, 16) != crc16(body):
            return None
        kind, dev, ver, payload = body.split(":", 3)
        return kind, dev, int(ver), payload
    except ValueError:
        return None


def parse_cfg(ver, text):
    # "i=500;th=28;g=18" -> dict, or None if any key/value is unknown or out of range
    cfg = {"v": ver}
    try:
        for pair in text.split(";"):
            key, value = pair.split("=")
            lo, hi = LIMITS[key]
            if not lo <= int(value) <= hi:
                return None
            cfg[key] = int(value)
    except (KeyError, ValueError):
        return None
    return cfg if len(cfg) == len(LIMITS) + 1 else None


def device_id():
    try:
        import machine               # identity: the chip's unique id, never a typed-in name
        return "".join("%02x" % b for b in machine.unique_id())[-6:]
    except ImportError:
        return "stub"


def new_state(dev):
    return {"dev": dev, "cfg": dict(FACTORY), "stats": {"applied": 0, "rejected": 0}}


def apply(state, cfg):
    if cfg["g"] != state["cfg"]["g"]:
        radio.config(group=cfg["g"])
    state["cfg"] = cfg
    state["stats"]["applied"] += 1


def on_message(state, msg, now):
    kind, dev, ver, payload = msg
    if dev != state["dev"] or kind != "C":
        return
    if ver <= state["cfg"]["v"]:
        radio.send(encode("A", dev, state["cfg"]["v"]))     # already running: ack again
        return
    cfg = parse_cfg(ver, payload)
    if cfg is None:
        state["stats"]["rejected"] += 1
        radio.send(encode("N", dev, ver))
        return
    apply(state, cfg)                                        # one-phase: run it now ...
    radio.send(encode("A", dev, ver))                        # ... and hope the ack arrives


def step(state, now):
    while True:
        try:
            text = radio.receive()
        except ValueError:
            text = "?"
        if text is None:
            return
        msg = decode(text)
        if msg:
            on_message(state, msg, now)


def main():
    state = new_state(device_id())
    while True:
        step(state, running_time())
        sleep(10)


if __name__ == "__main__":
    main()

"""Lab 19 - gateway: accept or reject radio frames before they enter the system (BEFORE).

The gateway is the trust boundary: everything behind it (broker, store, alarms, the local model)
believes what it lets through. This version checks what L300 checked - the frame parses and its
CRC-16 matches - so it detects NOISE. It cannot detect an ATTACKER: anyone in radio range can
compute a CRC, and a recorded frame replayed later is still a perfectly valid frame.
"""
import json

import frame_auth


class Verifier:
    def __init__(self, keys=None, mode="crc"):
        self.keys, self.mode = keys or {}, mode
        self.stats = {"accepted": 0, "rejected": 0}
        self.log = []                                   # JSON lines: why a frame was rejected

    def reject(self, reason, text):
        self.stats["rejected"] += 1
        self.log.append(json.dumps({"reject": reason, "frame": text[:40]}))
        return None

    def check(self, text):
        """Return (dev, ctr, payload) for an accepted frame, else None."""
        try:
            dev, ctr, payload, tag = text.split(":")
            ctr = int(ctr)
        except ValueError:
            return self.reject("format", text)
        if int(tag, 16) != frame_auth.crc16(frame_auth.body(dev, ctr, payload).encode()):
            return self.reject("crc", text)
        self.stats["accepted"] += 1                     # parse + CRC ok -> trusted
        return dev, ctr, payload
